/**
 * Fallbacks are generated by the real scene, never drawn separately.
 * Boots the built site, renders each keyframe deterministically through
 * ?poster=<key> (no spring, no pointer, no ladder, activity zeroed), and encodes
 * AVIF under the byte budgets. The Open Graph image comes from the hero poster.
 *
 *   pnpm posters              # builds, renders, encodes, writes docs/POSTERS.md
 *   pnpm posters --skip-build # reuse the current dist
 */
import { spawnSync } from 'node:child_process';
import { existsSync, mkdirSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { chromium, type Browser } from 'playwright';
import sharp from 'sharp';
import { serve } from './serve';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const pub = join(root, 'public');
const KEYS = ['hero', 'strategy', 'design', 'build', 'launch'] as const;
type Key = (typeof KEYS)[number];

interface Variant {
  name: 'desktop' | 'mobile';
  width: number;
  height: number;
  budget: number;
  isMobile: boolean;
  hasTouch: boolean;
}

const VARIANTS: readonly Variant[] = [
  { name: 'desktop', width: 1600, height: 1000, budget: 55 * 1024, isMobile: false, hasTouch: false },
  { name: 'mobile', width: 900, height: 1200, budget: 40 * 1024, isMobile: true, hasTouch: true }
];

const QUALITIES = [64, 56, 48, 42, 36, 30, 24, 20] as const;

interface Encoded { buf: Buffer; quality: number }

async function encodeAvif(png: Buffer, budget: number, label: string): Promise<Encoded> {
  let smallest: Encoded | null = null;
  for (const quality of QUALITIES) {
    const buf = await sharp(png).avif({ quality, effort: 6, chromaSubsampling: '4:2:0' }).toBuffer();
    if (!smallest || buf.byteLength < smallest.buf.byteLength) smallest = { buf, quality };
    if (buf.byteLength <= budget) return { buf, quality };
  }
  throw new Error(
    `${label}: ${smallest?.buf.byteLength ?? '?'}B exceeds the ${budget}B budget at every quality step`
  );
}

async function capture(
  browser: Browser,
  url: string,
  key: Key,
  v: Variant
): Promise<Buffer> {
  const context = await browser.newContext({
    viewport: { width: v.width, height: v.height },
    deviceScaleFactor: 1,
    isMobile: v.isMobile,
    hasTouch: v.hasTouch,
    reducedMotion: 'reduce'
  });
  const page = await context.newPage();
  const errors: string[] = [];
  page.on('pageerror', (e) => errors.push(String(e)));

  try {
    await page.goto(`${url}/?poster=${key}&noladder=1`, { waitUntil: 'load' });
    await page.evaluate(() => document.fonts.ready.then(() => undefined));
    await page.waitForFunction(() => window.__crease?.posterReady === true, null, { timeout: 30_000 })
      .catch(() => {
        throw new Error(
          `poster=${key} ${v.name}: the live scene never produced a frame. ` +
          `Posters must come from the real renderer; check that software WebGL2 is available.` +
          (errors.length ? ` Page errors: ${errors.join(' | ')}` : '')
        );
      });
    // One extra frame so the crossfade has fully settled before capture.
    await page.waitForTimeout(500);
    const stage = page.locator('[data-stage]');
    return await stage.screenshot({ type: 'png', animations: 'disabled' });
  } finally {
    await context.close();
  }
}

async function main(): Promise<void> {
  const skipBuild = process.argv.includes('--skip-build');
  if (!skipBuild || !existsSync(join(root, 'dist/index.html'))) {
    const built = spawnSync('pnpm', ['build'], { cwd: root, stdio: 'inherit', shell: process.platform === 'win32' });
    if (built.status !== 0) throw new Error('build failed');
  }

  mkdirSync(join(pub, 'posters'), { recursive: true });
  mkdirSync(join(pub, 'og'), { recursive: true });

  const server = await serve();
  const browser = await chromium.launch({
    args: [
      '--no-sandbox',
      '--use-gl=angle',
      '--use-angle=swiftshader',
      '--enable-unsafe-swiftshader',
      '--force-color-profile=srgb',
      '--hide-scrollbars'
    ]
  });

  const rows: string[] = [];
  let heroDesktopPng: Buffer | null = null;

  try {
    for (const v of VARIANTS) {
      for (const key of KEYS) {
        const png = await capture(browser, server.url, key, v);
        const meta = await sharp(png).metadata();
        if (meta.width !== v.width || meta.height !== v.height) {
          throw new Error(`${key}-${v.name}: captured ${meta.width}x${meta.height}, expected ${v.width}x${v.height}`);
        }
        const { buf, quality } = await encodeAvif(png, v.budget, `${key}-${v.name}`);
        const file = join(pub, 'posters', `${key}-${v.name}.avif`);
        writeFileSync(file, buf);
        rows.push(`| ${key} | ${v.name} | ${v.width}x${v.height} | ${buf.byteLength} | ${v.budget} | ${quality} |`);
        console.log(`${key}-${v.name}.avif  ${buf.byteLength}B  q${quality}`);
        if (key === 'hero' && v.name === 'desktop') heroDesktopPng = png;
      }
    }

    if (!heroDesktopPng) throw new Error('hero desktop frame missing');
    const og = await sharp(heroDesktopPng)
      .resize(1200, 630, { fit: 'cover', position: 'center' })
      .avif({ quality: 58, effort: 6 })
      .toBuffer();
    writeFileSync(join(pub, 'og', 'crease-hero.avif'), og);
    rows.push(`| og | desktop | 1200x630 | ${og.byteLength} | 122880 | 58 |`);
    console.log(`og/crease-hero.avif  ${og.byteLength}B`);
    if (og.byteLength > 120 * 1024) throw new Error('OG image exceeds 120KB');
  } finally {
    await browser.close();
    await server.close();
  }

  writeFileSync(
    join(root, 'docs', 'POSTERS.md'),
    `# Posters\n\nGenerated by \`pnpm posters\` from the live scene at \`?poster=<key>\`.\n` +
    `Headless Chromium, SwiftShader, deviceScaleFactor 1, sRGB, reduced motion, activity zeroed.\n` +
    `Mobile captures emulate a coarse pointer, so they render at Tier B exactly as a phone does.\n\n` +
    `| key | variant | size | bytes | budget | AVIF quality |\n|---|---|---|---|---|---|\n` +
    rows.join('\n') + '\n'
  );
  console.log('posters written; docs/POSTERS.md updated');
}

await main();
